import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';
import '../../services/api_service.dart';
class SchedulesScreen extends StatefulWidget{const SchedulesScreen({super.key});@override State<SchedulesScreen> createState()=>_SchedulesScreenState();}
class _SchedulesScreenState extends State<SchedulesScreen>{List schedules=[],teachers=[],students=[];bool loading=true;String? error;List<dynamic> list(dynamic x){if(x is List)return List<dynamic>.from(x);if(x is Map&&x['data'] is List)return List<dynamic>.from(x['data']);if(x is Map&&x['data'] is Map&&x['data']['data'] is List)return List<dynamic>.from(x['data']['data']);return[];}int id(dynamic x)=>int.tryParse('${x['id']}')??0;void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));@override void initState(){super.initState();load();}
Future<void> load()async{if(mounted)setState(()=>loading=true);Object? primary;try{final r=await ApiService.get('schedules');if(mounted)setState(()=>schedules=list(r));}catch(e){primary=e;}try{final r=await ApiService.get('teachers');if(mounted)setState(()=>teachers=list(r));}catch(_){ }try{final r=await ApiService.get('students');if(mounted)setState(()=>students=list(r));}catch(_){ }if(mounted){setState(()=>loading=false);if(primary!=null)msg(primary!);}}
Future<void> add()async{if(teachers.isEmpty){msg(Exception('أضف مدرسًا أولًا'));return;}String type='private';int teacherId=id(teachers.first);int? studentId=students.isEmpty?null:id(students.first);final group=TextEditingController(),subject=TextEditingController(),start=TextEditingController(),end=TextEditingController(),zoom=TextEditingController();final k=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(d)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('إضافة جدول / حصة'),content:Form(key:k,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(value:type,items:const[DropdownMenuItem(value:'private',child:Text('فردية')),DropdownMenuItem(value:'group',child:Text('مجموعة'))],onChanged:(v){if(v!=null)set(()=>type=v);}),DropdownButtonFormField<int>(value:teacherId,items:teachers.map<DropdownMenuItem<int>>((x)=>DropdownMenuItem(value:id(x),child:Text('${x['name']??''}'))).toList(),onChanged:(v){if(v!=null)set(()=>teacherId=v);}),if(type=='private'&&students.isNotEmpty)DropdownButtonFormField<int>(value:studentId,items:students.map<DropdownMenuItem<int>>((x)=>DropdownMenuItem(value:id(x),child:Text('${x['name']??''}'))).toList(),onChanged:(v)=>set(()=>studentId=v)),if(type=='group')TextFormField(controller:group,decoration:const InputDecoration(labelText:'اسم المجموعة'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:subject,decoration:const InputDecoration(labelText:'المادة'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:start,decoration:const InputDecoration(labelText:'البداية YYYY-MM-DD HH:MM'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:end,decoration:const InputDecoration(labelText:'النهاية YYYY-MM-DD HH:MM'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:zoom,decoration:const InputDecoration(labelText:'رابط Zoom أو فيديو (اختياري)'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(k.currentState!.validate())Navigator.pop(d,true);},child:const Text('حفظ'))])));if(ok==true){try{await ApiService.post('schedules',{'teacher_id':teacherId,'student_id':type=='private'?studentId:null,'group_name':type=='group'?group.text.trim():null,'subject':subject.text.trim(),'starts_at':start.text.trim(),'ends_at':end.text.trim(),'zoom_url':zoom.text.trim().isEmpty?null:zoom.text.trim()});await load();}catch(e){msg(e);}}for(final c in[group,subject,start,end,zoom])c.dispose();}
Future<void> openUrl(String raw)async{final u=Uri.tryParse(raw);if(u!=null&&await canLaunchUrl(u)){await launchUrl(u,mode:LaunchMode.externalApplication);}else{msg(Exception('الرابط غير صالح أو لا يمكن فتحه'));}}
@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('الجداول والحصص'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton(onPressed:add,child:const Icon(Icons.add)),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:schedules.length,itemBuilder:(_,i){final x=schedules[i],t=x['teacher'],s=x['student'],url='${x['zoom_url']??''}';return Card(child:ListTile(title:Text('${x['subject']??'حصة'}'),subtitle:Text('${x['starts_at']??''}\nالمدرس: ${t is Map?(t['name']??''):'غير محدد'}${s is Map?'\nالطالب: ${s['name']??''}':''}${x['group_name']!=null?'\nالمجموعة: ${x['group_name']}':''}'),isThreeLine:true,trailing:url.isEmpty?null:IconButton(icon:const Icon(Icons.video_call),tooltip:'فتح الرابط',onPressed:()=>openUrl(url))));})));}}
